function mount(host,s){const frame=host.querySelector('.live-scene-frame');if(!frame)return;const a=info(s),now=Date.now(),key=String(s.seed);if(track(s))active={key,index:a.index,start:now};if(!active||active.key!==key||active.index!==a.index||now-active.start>2000||s.ended)return;if(frame.querySelector('.age-celebration'))return;const node=host.createElement('div');node.className='age-celebration';node.setAttribute('role','status');node.setAttribute('aria-live','polite');node.innerHTML='<span class="age-celebration-label">'+escape(a.stage.name)+'</span>';
 if(!root.matchMedia?.('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<32;i++){const part=host.createElement('i');part.className='age-confetti';part.setAttribute('aria-hidden','true');part.style.cssText='--x:'+((i*37)%100)+'%;--drift:'+(((i*23)%81)-40)+'px;--turn:'+(180+i*29)+'deg;--delay:'+((i%7)*.045)+'s;--elapsed:'+(-(now-active.start)/1000)+'s;--color:'+['#e887ab','#d4c76b','#85b4ba','#a99bc4','#92b782'][i%5];node.append(part);}}
 frame.append(node);clearTimeout(cleanup);cleanup=setTimeout(()=>{node.remove();active=null;},Math.max(0,2000-(now-active.start)));}
